          "definition": "يُقصد بـ (إنشاء Mocks وStubs) أحد المفاهيم المحورية في مسار اختبارات Node.js ضمن بيئة Node.js؛ حيث يوفر للمهندس الأدوات المعمارية والبرمجية لمعالجة تدفقات البيانات وتقديم أداء عالي الاستقرار في بيئات الإنتاج الحية.",
