          "analogy": "يشبه الـ Mocking الاستعانة بدمية عرض الأزياء بدلاً من شخص حقيقي؛ تؤدي الغرض المطلوب لقياس مقاس الفستان دون تكلفة إضافية.",
          "why": "تبرز أهمية (اختبار Authentication) في حل مشكلات الاختناق البرمجي، ضمان استقرار الخدمات الخلفية عند تزايد أحمال المستخدمين، وفصل المسؤوليات لتحقيق كود نظيف وسهل الصيانة والاختبار.",
